// 从内联的 PCT_DATA[] 构建百分位表（参数已弃用：数据不再从文件读取）。
// 格式：连续 60392 组 (int32 score 小端, float32 percentile 小端)，score 升序。
static bool loadPercentiles(const char*) {
    g_pct.clear();
    g_pct.reserve(PCT_COUNT);
    const unsigned char* p = PCT_DATA;
    for (unsigned int i = 0; i < PCT_COUNT; i++) {
        int k; float v;
        memcpy(&k, p, 4); p += 4;
        memcpy(&v, p, 4); p += 4;
        g_pct.push_back(std::make_pair(k, v));
    }
    return true;
}

// 总 EP -> 百分位（0~100，越大代表超过越多人的得分）
static float percentileForScore(ll e) {
    int lo = 0, hi = (int)g_pct.size() - 1, s = -1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        if (g_pct[mid].first <= e) { s = mid; lo = mid + 1; } else hi = mid - 1;
    }
    return s < 0 ? 0.0f : g_pct[s].second;
}

// 卡片等级（按总 EP 百分位）：trash/common/uncommon/rare/epic/anomaly/mythic
static const char* cardTier(float p) {
    if (p < 1) return "trash";
    if (p < 50) return "common";
    if (p < 75) return "uncommon";
    if (p < 90) return "rare";
    if (p < 95) return "epic";
    if (p < 99) return "anomaly";
    return "mythic";
}
// 徽章稀有度（按 EP 绝对值）
static const char* badgeTier(ll score) {
    if (score < 1000) return "common";
    if (score < 10000) return "uncommon";
    if (score < 100000) return "rare";
    if (score < 1000000) return "epic";
    if (score < 10000000) return "anomaly";
    return "mythic";
}
// 同分显示序（对齐官网页面实测：元素徽章按原子序降序 9,8,7,6,5,4,3,2,1；
// LIFTOFF 先于 EVEN/ODD；其余徽章返回 1000 保持表序）
static int displayRank(const char* id) {
    static const struct { const char* id; int r; } T[] = {
        { "FLUORINE", 1 }, { "OXYGEN", 2 }, { "NITROGEN", 3 }, { "CARBON", 4 },
        { "BORON", 5 }, { "BERYLLIUM", 6 }, { "LITHIUM", 7 }, { "HELIUM", 8 },
        { "HYDROGEN", 9 }, { "LIFTOFF", 10 }, { "EVEN", 11 }, { "ODD", 12 },
    };
    for (size_t i = 0; i < sizeof(T) / sizeof(T[0]); i++)
        if (!std::strcmp(id, T[i].id)) return T[i].r;
    return 1000;
}
// 官网官方定义序 k 表（c00485 chunk verbatim）：
//   let k=new Map((N.find(e=>"periodic-table"===e.id)?.badgeIds??[]).map((e,a)=>[e,a]));
//   periodic-table 组 badgeIds = HYDROGEN,HELIUM,LITHIUM,BERYLLIUM,BORON,CARBON,NITROGEN,OXYGEN,FLUORINE（原子序升序）
//   G() 同分时按 k 升序；不在表中的徽章 k=Infinity。
// 该口径曾用于徽章出现序，但会让「同分时后一枚插到前一枚下面」，破坏从下往上的观感：
// 例 555515 的 SEMI_CLEAN 与 EQUILIBRIUM 同为 1000 EP，k 口径下 SEMI_CLEAN 先出现（在下方），
// 紧接着 EQUILIBRIUM 被插到它下面 → 视觉上突然往回跳。
// 现在出现序改为「显示序的严格倒序」（见 writeHtml），每枚新徽章必定落在上一枚上方；
// 元素徽章两种口径顺序本来就一致（显示序 FLUORINE→HYDROGEN，倒序即 HYDROGEN→FLUORINE = 原子序升序），
// 所以官网观感不受影响。
// 计分徽章统一排序：按 EP 降序；同 EP 按官网显示序（元素原子序降序 / LIFTOFF 先于 EVEN、ODD），再按表序
// 控制台输出与结果页共用，保证与官网显示一致
static std::vector<const Badge*> orderedBadges(const std::vector<const Badge*>& scoring) {
    std::vector<const Badge*> ordered = scoring;
    std::sort(ordered.begin(), ordered.end(),
              [](const Badge* a, const Badge* b) {
                  if (a->score != b->score) return a->score > b->score;
                  int ra = displayRank(a->id), rb = displayRank(b->id);
                  if (ra != rb) return ra < rb;
                  return (a - &BADGES[0]) < (b - &BADGES[0]);
              });
    return ordered;
}
// 百分位颜色：官网 getPercentileColor（p=超过人数百分比）
static const char* pctClsOf(float p) {
    if (p >= 95) return "pct-yellow";
    if (p >= 80) return "pct-green";
    if (p >= 50) return "pct-emerald";
    if (p >= 20) return "pct-orange";
    return "pct-red";
}

// 百分位文案：Top X% / Bottom X%（formatPercentile）
static std::string formatPercentile(float p) {
    if (p >= 50.0f) { int t = (int)llround(100.0 - p); return t == 0 ? "Top <1%" : "Top " + std::to_string(t) + "%"; }
    int t = (int)llround(p);
    return t == 0 ? "Bottom <1%" : "Bottom " + std::to_string(t) + "%";
}
// 千分位逗号
static std::string withCommas(ll v) {
    std::string s = std::to_string(v), out;
    int c = 0;
    for (int i = (int)s.size() - 1; i >= 0; i--) {
        out += s[i];
        if (++c % 3 == 0 && i > 0) out += ',';
    }
    std::reverse(out.begin(), out.end());
    return out;
}
// 分享文本方块（官网 ShareButton 映射：trash🟫 common⬜ uncommon🟩 rare🟦 epic🟪 anomaly🟧 mythic🟥）
static const char* sqOf(const char* tier) {
    if (!std::strcmp(tier, "trash"))    return "\xF0\x9F\x9F\xAB"; // 🟫
    if (!std::strcmp(tier, "uncommon")) return "\xF0\x9F\x9F\xA9"; // 🟩
    if (!std::strcmp(tier, "rare"))     return "\xF0\x9F\x9F\xA6"; // 🟦
    if (!std::strcmp(tier, "epic"))     return "\xF0\x9F\x9F\xAA"; // 🟪
    if (!std::strcmp(tier, "anomaly"))  return "\xF0\x9F\x9F\xA7"; // 🟧
    if (!std::strcmp(tier, "mythic"))   return "\xF0\x9F\x9F\xA5"; // 🟥
    return "\xE2\xAC\x9C";                                          // ⬜ common
}

