    h += ".t-common{--g:linear-gradient(135deg,#f3f4f6,#fff 50%,#f3f4f6);--tb:#9ca3af;--glow:none;--ig:inset 0 0 18px rgba(156,163,175,.10);--tx:#374151;--pt:#4b5563;--pb:#f3f4f6;--pbd:#d1d5db;--fb:#e5e7eb;--bg:linear-gradient(135deg,rgba(249,250,251,.6),#fff,rgba(249,250,251,.6));--fglow:none}\n";
