    h += ".t-uncommon{--g:linear-gradient(135deg,#d1fae5,#f0fdf4 50%,#d1fae5);--tb:#6ee7b7;--glow:0 0 8px rgba(16,185,129,.15);--ig:inset 0 0 18px rgba(110,231,183,.15);--tx:#065f46;--pt:#15803d;--pb:#f0fdf4;--pbd:#86efac;--fb:#a7f3d0;--bg:linear-gradient(135deg,rgba(236,253,245,.4),#fff,rgba(236,253,245,.4));--fglow:0 0 10px rgba(16,185,129,.25)}\n";
