    h += ".t-rare{--g:linear-gradient(135deg,#dbeafe,#f0f9ff 50%,#dbeafe);--tb:#93c5fd;--glow:0 0 10px rgba(59,130,246,.2);--ig:inset 0 0 18px rgba(147,197,253,.18);--tx:#1e40af;--pt:#1d4ed8;--pb:#eff6ff;--pbd:#93c5fd;--fb:#bfdbfe;--bg:linear-gradient(135deg,rgba(239,246,255,.45),#fff,rgba(239,246,255,.45));--fglow:0 0 12px rgba(59,130,246,.3)}\n";
