    h += ".t-epic{--g:linear-gradient(135deg,#ede9fe,#fdf4ff 50%,#ede9fe);--tb:#d8b4fe;--glow:0 0 12px rgba(168,85,247,.2);--ig:inset 0 0 18px rgba(216,180,254,.18);--tx:#6b21a8;--pt:#7e22ce;--pb:#faf5ff;--pbd:#d8b4fe;--fb:#e9d5ff;--bg:linear-gradient(135deg,rgba(250,245,255,.45),#fff,rgba(250,245,255,.45));--fglow:0 0 15px rgba(168,85,247,.35)}\n";
    h += ".dark .t-epic{--g:linear-gradient(135deg,rgba(88,28,135,.6),#27272a 50%,rgba(88,28,135,.6));--tb:#6b21a8;--glow:0 0 16px rgba(168,85,247,.4);--ig:inset 0 0 18px rgba(88,28,135,.3);--tx:#c084fc;--pt:#c084fc;--pb:rgba(59,7,100,.5);--pbd:rgba(107,33,168,.6);--fb:rgba(107,33,168,.6);--bg:linear-gradient(135deg,rgba(59,7,100,.5),var(--surface),rgba(59,7,100,.5));--fglow:0 0 15px rgba(168,85,247,.35)}\n";
    h += ".t-anomaly{--g:linear-gradient(135deg,#fed7aa,#fffbeb 50%,#fed7aa);--tb:#fdba74;--glow:0 0 14px rgba(249,115,22,.2);--ig:inset 0 0 18px rgba(253,186,116,.18);--tx:#9a3412;--pt:#c2410c;--pb:#fff7ed;--pbd:#fdba74;--fb:#fed7aa;--bg:linear-gradient(135deg,rgba(255,247,237,.45),#fff,rgba(255,247,237,.45));--fglow:0 0 18px rgba(249,115,22,.4)}\n";
    h += ".dark .t-anomaly{--g:linear-gradient(135deg,rgba(124,45,18,.6),#27272a 50%,rgba(124,45,18,.6));--tb:#9a3412;--glow:0 0 18px rgba(249,115,22,.4);--ig:inset 0 0 18px rgba(124,45,18,.3);--tx:#fb923c;--pt:#fb923c;--pb:rgba(67,20,7,.5);--pbd:rgba(154,52,18,.6);--fb:rgba(154,52,18,.6);--bg:linear-gradient(135deg,rgba(67,20,7,.5),var(--surface),rgba(67,20,7,.5));--fglow:0 0 18px rgba(249,115,22,.4)}\n";
    h += ".t-mythic{--g:linear-gradient(135deg,#ffe4e6,#faf5ff 50%,#cffafe);--tb:#f9a8d4;--glow:0 0 16px rgba(236,72,153,.2),0 0 28px rgba(168,85,247,.08);--ig:inset 0 0 18px rgba(249,168,212,.18);--tx:#111827;--pt:#b91c1c;--pb:#fef2f2;--pbd:#f9a8d4;--fb:#fbcfe8;--bg:linear-gradient(135deg,rgba(255,228,230,.35),rgba(250,245,255,.25),rgba(207,250,254,.35));--fglow:0 0 20px rgba(236,72,153,.45)}\n";
    h += ".dark .t-mythic{--g:linear-gradient(135deg,rgba(136,19,55,.55),rgba(88,28,135,.45) 50%,rgba(22,78,99,.55));--tb:#9d174d;--glow:0 0 20px rgba(236,72,153,.4),0 0 36px rgba(168,85,247,.2);--ig:inset 0 0 18px rgba(157,23,77,.3);--tx:#f3f4f6;--pt:#f87171;--pb:rgba(69,10,10,.5);--pbd:rgba(157,23,77,.6);--fb:rgba(157,23,77,.6);--bg:linear-gradient(135deg,rgba(136,19,55,.5),rgba(88,28,135,.4),rgba(22,78,99,.5));--fglow:0 0 20px rgba(236,72,153,.45)}\n";
    // 基础样式
